with recent_shipments as (select * from shipments where status = 'RETURNED'), Summary as (select case when cost >= 95 then 'high' when cost >= 14 then 'mid' else 'low' end as cost_bucket, concat_ws(', ', sort_array(collect_set(status))) as status_values, sum(case when carrier = 'Flash' then cost else 0 end) as flash_cost from recent_shipments group by case when cost >= 95 then 'high' when cost >= 14 then 'mid' else 'low' end) select * from Summary where flash_cost > 62;
